import {p,code,table,req,diagram,qa,refs,warn,section as s} from './lesson-helpers.mjs';
export const additionalLessons=[
{
slug:'networking',title:'Networking & HTTP',heading:'Follow a request from a hostname to a response',intro:'Understand the layers beneath an API call before diagnosing connection failures, slow requests and gateway timeouts.',definition:'Networking provides addressing, transport and communication between processes. HTTP defines request/response semantics above the transport; DNS resolves names, TCP provides an ordered byte stream, and TLS protects the connection’s confidentiality and authenticated peer identity.',prerequisites:'Know an HTTP endpoint from <a href="index.html#contract">API Design</a>. No prior TCP, DNS or TLS knowledge is assumed.',outcome:'Locate delay or failure at the correct network layer and configure connection reuse, trust and time budgets intentionally.',
sections:[
s('problem','Why “the API is slow” is not a diagnosis',p('A Spring service calls https://payments.example.com/capture. Before the provider can process the JSON, the caller needs an address, a reachable peer, an appropriate secure connection and permission to send the request. An error at any earlier layer can look like “payment failed” in a badly designed log.')+p('Follow a new connection first. DNS maps the name to records containing addresses. TCP establishes a connection to a selected IP/port. TLS negotiates protection and validates the peer under a trust policy. HTTP then sends the method, target, headers and body. An existing pooled connection may skip most of that setup; a proxy may perform some steps on the caller’s behalf.')),
s('requirements','Write connectivity and user-facing requirements',req(['Reach the intended provider and send a valid HTTP request.','Reuse suitable connections and return meaningful failures.','Drain connections safely during deployment.'],['Verify TLS peer identity; no disabled certificate checks.','Bound connect, pool-wait and response time within a total deadline.','Illustrative p95 status call below 200 ms.','Never infer remote rollback from a connection failure.'])+p('The user cares about an outcome, but operators need a layer-specific error: DNS resolution, connection refusal, TLS validation, pool exhaustion, HTTP rejection or application timeout. Preserve that distinction without leaking credentials.')),
s('layers','Walk through the layers',diagram(['Resolve name','Connect IP:port','Establish TLS','Exchange HTTP'], 'This is a conceptual new HTTPS connection. Reuse, proxies and protocol choices can change which steps occur on a call.')+table(['Layer','What it establishes','What it cannot prove'],[['DNS','A name-to-record answer, subject to caching and resolver behavior','That the returned address is healthy or the application is authorized.'],['TCP','A connection and reliable ordered bytes while viable','That the business operation executed exactly once.'],['TLS','Encrypted transport and peer identity under configured validation','That an authenticated user may refund a particular order.'],['HTTP','Methods, representations, status and metadata','That a timeout means the remote side effect did not happen.']])+p('A port selects a listening service on a host; an IP identifies a network destination, not a specific Java object. A Kubernetes Service routes to eligible endpoints; a pod may listen on 8080 while the Service exposes port 80. Keep listener, Service and externally exposed ports distinct.')),
s('connections','Connection pools and HTTP versions',p('Opening TCP/TLS repeatedly consumes time and resources. A client pool reuses eligible connections and bounds concurrent use. Requests can wait for a connection even when network latency is low. Track pool-acquisition time separately from provider processing.')+p('HTTP/1.1 commonly uses multiple reusable connections for parallel requests. HTTP/2 multiplexes streams over a connection, reducing some connection overhead; TCP packet loss can still delay streams sharing that connection. HTTP/3 uses QUIC and has different transport behavior. Neither protocol automatically fixes an overloaded handler or an N+1 query.')+p('DNS records may change while connections remain open. Idle timeouts on clients, ALBs and proxies can disagree, creating stale-connection failures. Configure reuse, idle eviction and connection lifetime deliberately; retry only when the operation’s semantics permit it.')),
s('implementation','Implement clear budgets and trust',code('Conceptual client configuration (client-specific APIs differ):\n  pool acquisition timeout: 50 ms\n  TCP connect timeout: 100 ms\n  response/read timeout: 400 ms\n  total logical-call deadline: 600 ms including any retry\n  TLS: verify certificate chain AND intended hostname\n  connection pool: bounded per destination')+p('Spring RestClient/WebClient uses an underlying HTTP client whose pool and timeout configuration must be inspected. Construct clients through configured/instrumented builders where appropriate. A WebClient reactive return type does not guarantee every invoked dependency is nonblocking. Do not put a blocking SOAP call on an event-loop thread.')+p('On AWS, map client → DNS → ALB/API Gateway → ECS/EKS/Lambda → provider. Distinguish security-group routing/access from application authentication. If TLS terminates at the ALB, decide explicitly how the next hop is protected. Trust forwarding headers only from your controlled edge.')),
s('worked','Worked diagnosis: intermittent gateway timeouts',p('After scaling to 20 pods, provider calls intermittently wait for seconds, but provider execution remains 80 ms. Inspect per-pod pool wait and connection count before blaming DNS. Each pod opened its own large pool; the provider now hits a connection quota. Bound fleet-wide pressure and reduce pools/concurrent calls based on measured capacity.')+p('Next separate a 504 generated by the gateway from an exception generated by the client. Compare gateway access records, application trace and provider request reference. If capture may have committed before the gateway timed out, reconcile using the original intent; do not fix the symptom by blindly increasing every timeout.')+p('Validate with fresh and reused connections, idle gaps, DNS rotation, certificate rotation and controlled packet/delay faults in a nonproduction test environment. Confirm hostname validation remains enabled throughout.')),
s('pitfalls','Pitfalls and selection rules',table(['Symptom','First evidence','Likely action'],[['Pool wait high, provider fast','Active/idle pool and pending acquisitions','Bound concurrency and size pools within provider limits.'],['TLS fails after rotation','Trust chain, hostname, expiry and time','Repair trust/identity; do not bypass validation.'],['Only first call slow','DNS/connect/TLS phase timings','Evaluate connection reuse and startup warmup.'],['Connection reset after idle','Client/proxy idle policies','Align eviction/reuse and safe retry rules.']])+warn('Client disconnect or cancellation does not undo work already accepted by the server. Connectivity and idempotency are related operationally but solve different problems.')),
s('interview','Interview ladder',qa([['Foundational','What does DNS do?','It resolves names to records through a resolver/cache hierarchy. It does not guarantee application health or authorization.'],['Foundational','Is HTTPS simply HTTP on another port?','HTTPS adds TLS protection and peer validation. Port conventions alone do not create encryption or prove identity.'],['Intermediate','Why can pool wait dominate latency?','Connections are finite. Slow calls or excessive concurrency can exhaust them, making later requests queue locally before reaching the provider.'],['Intermediate','Does HTTP/2 eliminate head-of-line blocking?','It multiplexes HTTP streams but runs over TCP; loss can delay all streams on that connection. Application queues and downstream contention also remain.'],['Advanced','How do you distinguish a gateway timeout from an application timeout?','Use phase timing, gateway logs, trace boundaries and provider references. Identify which component ended its wait and preserve unknown write outcome recovery.'],['Advanced','Should certificate validation be disabled during an incident?','No. Diagnose the chain, hostname, clocks and trust configuration. Disabling validation removes the peer-identity guarantee and creates a different failure/security mode.']])),
s('references','References and practice',refs([['https://www.rfc-editor.org/rfc/rfc9110','HTTP semantics','methods, intermediaries and status meanings.'],['https://www.rfc-editor.org/rfc/rfc9113','HTTP/2','streams and connection behavior.'],['https://docs.spring.io/spring-framework/reference/web/webflux-webclient/client-builder.html','Spring WebClient configuration','client transport configuration.'],['https://docs.aws.amazon.com/elasticloadbalancing/latest/application/introduction.html','AWS ALB','listeners, routing and targets.']])+p('<strong>Exercise:</strong> diagram your application’s actual TLS termination points and list where a timeout can originate.'))
]},
{
slug:'security',title:'Security & Identity',heading:'Verify the caller, then authorize the exact action',intro:'Build from one private order lookup to tokens, delegated access, tenant isolation, credential rotation and auditable decisions.',definition:'Authentication establishes a caller’s identity under a trust mechanism. Authorization decides whether that identity may perform a specific action on a specific resource. OAuth delegates access; OpenID Connect adds an identity layer for authentication flows.',prerequisites:'Understand <a href="networking.html#layers">TLS and HTTP</a> and an order resource from API Design. We define tokens and scopes before using Spring configuration.',outcome:'Design an authorization boundary that survives valid-but-wrong tokens, cross-tenant IDs and credential rotation.',sections:[
s('problem','A valid login can still access the wrong order',p('An endpoint receives GET /orders/ord_7 and a signed token. Checking only that the token is valid answers who called, not whose order ord_7 is. If the repository loads by ID without tenant/ownership checks, a legitimate customer can read another customer’s order. Guess-resistant identifiers reduce discovery but do not authorize access.')+p('Start with a rule: this caller can read orders in their tenant only when the relevant role/relationship permits it. Express that rule before choosing JWT or a gateway. The token supplies verified inputs; the application makes the resource-specific decision.')),
s('requirements','Threats become requirements',req(['Authenticate browser, mobile and partner clients.','Authorize order read, refund and administration separately.','Rotate credentials and audit sensitive actions.'],['No cross-tenant access or secret leakage.','Reject invalid issuer/audience/signature/time policy.','Bound credential/key discovery load.','Define revocation and audit-retention expectations.'])+p('Threat modeling asks what an attacker can submit, observe or influence. Include an authenticated malicious user, a compromised partner credential and a forged callback, not only anonymous traffic. Give every trust boundary an owner.')),
s('concepts','Sessions, tokens, scopes and claims',table(['Concept','Meaning','Boundary'],[['Session cookie','Browser sends a session reference/cookie under browser rules','Requires CSRF/session-lifecycle policy.'],['Access token','Credential presented to a resource server','Must be intended for this API and validated.'],['JWT','Signed/encoded claim format, not an authorization policy','Decoded text is not verified identity; encryption is separate.'],['Scope','Granted capability such as orders:read','Does not imply ownership of every order.'],['ID token','OIDC token for the client’s authentication context','Not a substitute for the API’s access token.']])+p('For an appropriate user-facing client, authorization code with PKCE protects the code exchange; validate redirect URIs and the complete flow. Client credentials fits machine identity where supported. Do not invent a token protocol from base64 JSON or store a client secret in a distributed mobile app.')),
s('validation','Walk one request through policy',diagram(['Verify transport/token','Establish principal','Load scoped resource','Authorize and audit'], 'Rejecting a token and denying access to a valid principal are different outcomes.')+code('Order order = repository.findByTenantAndId(verifiedTenant(), orderId)\n    .orElseThrow(NotFoundException::new);\npolicy.requireCanRefund(principal(), order);\n// Check business state and record the authorized transition.\n// tenant supplied in the body is not authority.')+p('Verify allowed signing algorithms, trusted issuer, expected audience, expiry and relevant time claims. Plan key rotation and clock tolerance. Fetch keys only from configured trusted discovery endpoints; an untrusted token must not choose an arbitrary key URL. Choose 401/403 and any existence-hiding 404 policy consistently.')),
s('implementation','Spring and AWS mapping',p('Spring Security resource-server support supplies JWT verification machinery. Configure issuer and audience validation explicitly for the chosen version, and combine route/method checks with domain policy and tenant-scoped repository operations. Avoid relying on a controller-only annotation if internal paths can bypass the same rule.')+p('Cognito or another identity provider issues credentials; API Gateway can validate suitable tokens at the edge. Application authorization remains necessary. mTLS authenticates a peer connection, not the end user’s refund rights. Store signing material/provider secrets in managed secret storage with least-privilege access and tested rotation.')+p('For browser cookie authentication, assess CSRF because browsers attach cookies automatically. CORS controls browser cross-origin access; it does not stop a nonbrowser caller and is not authentication. For callbacks, prevent SSRF with destination validation and restricted egress, including redirect/DNS behavior.')),
s('worked','Worked design: partner refunds',p('A partner gets an access token intended for the orders API with a refund capability. Map its verified subject/client identity to one partner account. Resolve the order using that partner scope; enforce refundable state and amount limits in a transaction; create a durable refund intent with idempotency identity.')+p('Audit actor, action, resource, decision, time and stable request/business references without storing bearer tokens or card data. A short-lived token can reduce revocation exposure, but the actual revocation contract may require introspection or explicit state. During signing-key rotation, overlap trusted keys and observe unknown-key errors before removing the old key.')+p('Test a valid token for another audience, another tenant’s order ID, expired tokens, unknown key IDs, mass assignment of tenant/role fields, and a rotated key. Verify both allowed and denied decisions; happy-path login tests cannot prove tenant isolation.')),
s('pitfalls','Pitfalls and operational decisions',table(['Issue','Reasoning'],[['JWT revocation','Stateless verification does not automatically learn revocation. Define lifetime and any revocation/introspection state.'],['Authorization caching','Cached allow decisions can outlive permission changes. State the revocation freshness bound.'],['Secret rotation','Replacing a value is not sufficient if clients keep old pooled/configured credentials. Verify rollout and overlap.'],['Overprivileged service','Internal network location is not sufficient authority. Validate identity and scope at the resource boundary.'] ])),
s('interview','Interview ladder',qa([['Foundational','Authentication versus authorization?','Authentication establishes identity; authorization applies action/resource policy to that identity.'],['Foundational','Is a decoded JWT trustworthy?','No. Validate signature and trust/claim policy before using its contents as identity.'],['Intermediate','OAuth versus OIDC?','OAuth delegates access to resources; OIDC adds identity/authentication semantics on top of OAuth flows.'],['Intermediate','Why is a scope check insufficient?','A broad capability does not prove tenant membership, resource ownership, amount limits or current business state.'],['Advanced','How do you revoke JWT access quickly?','Choose short lifetimes and, if required, introspection/revocation state or another explicit protocol. State latency/availability trade-offs rather than promising immediate stateless revocation.'],['Advanced','How do you prove isolation?','Exercise valid credentials across tenant/resource combinations at every entry path, inspect query scoping, and assert denied requests cause no side effects or sensitive disclosure.']])),
s('references','References and practice',refs([['https://datatracker.ietf.org/doc/html/rfc9700','OAuth security best current practice','flow and attack mitigations.'],['https://openid.net/specs/openid-connect-core-1_0.html','OIDC Core','identity and token semantics.'],['https://docs.spring.io/spring-security/reference/servlet/oauth2/resource-server/jwt.html','Spring Security JWT','validation and resource-server configuration.'],['https://owasp.org/API-Security/','OWASP API Security','object authorization, resource use and SSRF.']])+p('<strong>Exercise:</strong> write an authorization matrix for one resource: caller class × action × ownership × business state.'))
]},
{
slug:'consistency',title:'Consistency & Distributed Transactions',heading:'State what readers may see and which changes must agree',intro:'Move from one transaction to replicated reads and multi-service workflows without confusing local atomicity, consistency models and business compensation.',definition:'A consistency model defines permitted observations of concurrent operations. A distributed transaction coordinates atomic commitment across participants; a saga instead coordinates local commits with explicit recovery and compensation semantics.',prerequisites:'Read <a href="databases.html#transactions">local transactions</a> and <a href="messaging.html#outbox">the outbox</a>. Keep a payment and inventory reservation as the running example.',outcome:'Choose a consistency guarantee per operation and explain intermediate states, partition behavior and recovery.',sections:[
s('problem','The order exists on one copy but not another',p('Checkout commits an order on the writer. The next GET reaches a delayed replica and returns not found. Neither response is necessarily a storage bug: the application used two read paths with different freshness. The missing design decision is which observations the caller was promised.')+p('Now split payment and inventory into services. Payment commits, inventory fails, and there is no single local transaction to undo both. Reader freshness and multi-service atomicity are separate problems. We will define observations first, then coordinate changes.')),
s('requirements','Choose guarantees by operation',req(['Create order and immediately retrieve its accepted state.','Reserve inventory and authorize payment across services.','Expose workflow progress and reconcile partial completion.'],['Read-your-writes for the order-creation experience.','Never confirm fulfillment without its prerequisites.','Permit delayed analytics/search projections.','Define behavior when components cannot communicate.'])+p('Uniform “strong consistency everywhere” can impose cost without solving a business need. Define current-state reads for money decisions, session guarantees for a user experience, and bounded/documented lag for projections. State whether a write acknowledgement represents local durability or replicated commitment.')),
s('models','Explain the observations',table(['Guarantee','Intuition','Nuance'],[['Linearizability','Each operation appears to take effect at one point between invocation and completion','Requires the specified operation/system scope, not merely a replica count.'],['Read-your-writes','A caller sees their own completed writes','Does not imply every caller sees one global order.'],['Causal consistency','Causally related operations are observed in causal order','Concurrent unrelated operations need additional conflict policy.'],['Eventual consistency','Copies converge if updates stop and the protocol progresses','Does not by itself specify maximum lag or conflict meaning.']])+p('Serializable isolation concerns equivalence to a serial transaction order; it does not automatically imply real-time ordering across clients. Name the guarantee and scope rather than using “consistent” as an unexplained adjective.')),
s('partitions','Quorum, partitions and split-brain',p('A network partition prevents some nodes communicating even when the nodes are alive. For an invariant requiring one authoritative order, disconnected writers cannot safely invent independent answers indefinitely. Some operations must reject/wait, or the system must accept conflicting states and reconcile them according to the domain.')+p('A quorum is a required subset of participants. In common replicated designs, intersecting read/write sets can help ensure overlap, but R+W>N alone is not a proof of linearizability. Membership, version reconciliation, concurrent writers, sloppy quorum behavior and failure handling matter.')+p('Split-brain means more than one node/group acts as authority for the same work. Prevent stale leaders from committing protected effects with correctly enforced terms/epochs or fencing at the resource boundary. A lease that expires on a coordinator does not automatically stop an old paused process from acting.')),
s('coordination','Atomic commit versus saga',table(['Approach','Use when','Trade-off'],[['One local transaction','All critical data can share an appropriate store/owner','Simpler invariant; less independent ownership.'],['Two-phase commit','Participants/protocol support atomic commit and its operational cost is acceptable','Coordinator/participant failures can block progress in relevant designs.'],['Saga','Business permits visible intermediate states and compensation','Compensation can fail and is not an automatic rollback.']])+diagram(['Reserve stock','Authorize payment','Confirm order','Recover or compensate'], 'Each saga step is a durable local transition. A later failure creates new work, not time travel.')+p('Refunding a charge is a new financial operation; it may have fees, timing constraints or fail. Releasing a reservation is only valid while its state allows it. Store step identity, status and retry/compensation evidence durably. Avoid a saga for an invariant that the business genuinely requires to be invisible and atomic.')),
s('implementation','Spring and AWS boundaries',code('Workflow ledger (illustrative):\n orderId, step, commandId, state, version, lastError\n conditional transition: RESERVED -> PAYMENT_PENDING\n remote call: stable payment intent identity\n unknown outcome: reconcile before compensation decision\n outbox: publish only committed local transitions')+p('Spring @Transactional covers the configured local resources. It does not make calls to unrelated payment and stock services atomic. A durable orchestrator can use RDS plus workers, or AWS Step Functions when its state/retry model fits. Choreography uses events instead; it still needs ownership, timeouts and a way to inspect the full workflow.')+p('For DynamoDB, verify the selected consistency mode and exact access path, including secondary indexes and global-table configuration. Never infer multi-region money invariants from a generic product label or from a local strongly consistent read option.')),
s('worked','Worked design: payment succeeds, stock expires',p('Create a reservation with expiry and durable state. Payment authorization uses a stable intent. If payment completes while reservation remains RESERVED, conditionally confirm it. If expiry won the transition, do not force the order to paid-and-fulfillable: try a new reservation under policy, void an authorization, or issue a refund as appropriate.')+p('Keep UNKNOWN payment separate from DECLINED. Reconcile the original provider operation before deciding a compensation that could conflict with late success. Use unique command identities and conditional transitions so duplicate callbacks cannot release stock twice or confirm a refunded order.')+p('Test late success, duplicate expiry, paused coordinator recovery, provider unavailability during compensation and repeated workflow replay. State what the customer sees in every intermediate state and how operators resolve the unresolved tail.')),
s('pitfalls','Pitfalls and decision criteria',warn('A compensating action is not guaranteed to restore the exact original world. Emails have been read, stock may have been sold, and refunds can be delayed. Define domain recovery rather than saying “roll back the saga.”')+p('Choose one owner for the invariant when possible. Use replicas/projections for permitted lag. Require atomic coordination only where the contract needs it, and budget the availability/latency cost. Review the design under partitions, not only clean sequential failures.')),
s('interview','Interview ladder',qa([['Foundational','Eventual consistency versus immediate visibility?','Eventual convergence permits temporary differences; immediate visibility/read-your-writes requires a stronger selected path or protocol.'],['Foundational','Is compensation a rollback?','No. It is a new domain action intended to offset an earlier effect and can itself fail or be incomplete.'],['Intermediate','Does R+W>N prove linearizability?','No. It describes overlap under assumptions; versions, concurrent writes, membership and failure/reconciliation semantics determine the real guarantee.'],['Intermediate','Can @Transactional span arbitrary microservices?','Not automatically. It covers configured transactional resources; remote business calls need an explicit coordination/recovery protocol.'],['Advanced','When is a saga inappropriate?','When required invariants cannot tolerate visible intermediate states or meaningful compensation is impossible, unless the contract is changed or a different coordination boundary is chosen.'],['Advanced','How do you handle late payment success after expiry?','Use conditional durable states, reconcile provider identity, and follow a documented re-reserve/void/refund policy. Never infer outcome solely from timeout or overwrite a newer state.']])),
s('references','References and practice',refs([['https://www.postgresql.org/docs/current/transaction-iso.html','PostgreSQL isolation','transaction-level guarantees.'],['https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/saga-orchestration.html','AWS saga orchestration','steps and compensation.'],['https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/HowItWorks.ReadConsistency.html','DynamoDB consistency','read-path-specific support.'],['https://raft.github.io/','Raft research','replicated logs, leadership and safety.']])+p('<strong>Exercise:</strong> mark which order operations need local atomicity, read-your-writes, delayed projection or explicit compensation.'))
]},
{
slug:'microservices',title:'Microservice Boundaries',heading:'Split ownership only when the boundary earns its cost',intro:'Grow a modular order application into independently owned services without creating a distributed monolith.',definition:'A service boundary assigns responsibility for business behavior and data to an independently operated component. A modular monolith enforces internal boundaries in one deployment; microservices make selected boundaries remote and independently deployable.',prerequisites:'Understand <a href="databases.html">data ownership</a> and <a href="messaging.html">remote messaging</a>. Start with one codebase; a service-per-table design is not assumed.',outcome:'Choose a boundary using invariants, change patterns, team ownership and operational cost, then migrate it safely.',sections:[
s('problem','One change requires six coordinated deployments',p('Orders, payment, inventory and receipt components run as separate services, yet every new field requires all six to deploy together. Their databases are cross-written and a checkout calls every service synchronously. There are many processes but little independent ownership: a distributed monolith.')+p('A network boundary has latency, failure and contract-evolution cost. Start by identifying a responsibility that can own its rules and data. Notification delivery is often easier to separate than an invariant requiring synchronous stock and order mutation. Logical modules let you discover boundaries before making them remote.')),
s('requirements','Define autonomy and invariants',req(['Own checkout, catalog, payment and notifications explicitly.','Change receipt behavior without deploying checkout.','Expose supported contracts instead of shared-table writes.'],['Each critical invariant has an owner.','Bound synchronous fan-out and failure propagation.','Independent delivery requires compatible contracts.','Teams can observe and operate what they own.'])+p('A bounded context defines a model in which terms have precise meaning. “Customer” in billing may differ from “customer” in marketing. A domain boundary is not inferred from matching noun names alone. Analyze workflows, shared invariants and reasons for change.')),
s('model','From modules to service ownership',table(['Evidence','Boundary implication'],[['Two operations must commit together for a hard invariant','Keep an appropriate common transactional owner or design explicit coordination.'],['A capability changes independently and has distinct load/lifecycle','Candidate for independent deployment.'],['Every request needs many chatty calls across the boundary','Revisit boundary or introduce a suitable projection/BFF.'],['Another service directly updates its tables','Ownership is bypassed regardless of repository layout.']])+p('Start with module interfaces and restricted data access in the monolith. Integration tests enforce allowed calls. Extract only when deployment, scaling, fault isolation or organizational autonomy benefits exceed extra operational complexity. A well-structured monolith is not a failure state.')),
s('communication','Synchronous decisions and asynchronous facts',p('Use a synchronous call when the caller needs a bounded answer now, such as an authorization decision. Use events for facts other owners may process later. A read model can avoid request-time fan-out: catalog data is projected into a browsing view, while checkout validates the current authoritative rule.')+diagram(['Checkout owner','Committed order + outbox','Notification owner','Delivery provider'], 'The receipt boundary is independent only if delivery delays do not invalidate checkout acceptance.')+p('Avoid sharing one giant DTO/entity jar across all services. A schema contract or generated client can be useful, but forced lockstep dependency updates undermine compatibility. Publish versions and behavioral guarantees at the boundary.')),
s('implementation','Modular Spring and AWS choices',p('In Spring, package modules around capabilities, expose narrow interfaces, and keep repositories internal. Spring Modulith can support module-oriented structure/testing for suitable applications; ArchUnit can enforce architectural constraints. These tools check structure, not whether you chose the right business boundary.')+p('Deploy independently on ECS/EKS/Lambda when needed. Use per-service credentials and data access policies. “Database per service” means exclusive ownership, not necessarily one physical server per tiny service. Shared infrastructure is possible if access, coupling and failure domains are understood.')+code('Boundary contract:\n Checkout publishes OrderAccepted(eventId, orderId, receiptAddressRef)\n Notifications owns delivery status and retry policy\n Notifications cannot UPDATE checkout.orders\n Checkout does not wait for email provider completion')+p('Store only the data a consumer needs under the applicable privacy rules. A replicated reference is not permission to treat stale copied data as authority for another owner’s invariant.')),
s('worked','Worked migration: extract notifications',p('First isolate notification code behind an internal interface. Add durable intent/outbox recording with the order transaction. Run a new notification consumer in shadow mode that records what it would send, without sending customer messages. Compare behavior, volume and missing intents.')+p('Switch effect ownership once: old sender stops, new sender starts under a coordinated flag/identity protocol. Preserve stable delivery identity so uncertain cutover retries do not duplicate messages. Keep compatibility for old events and rollback routing. Do not run both production senders blindly during migration.')+p('Validate outage independence: kill notification workers, confirm checkout accepts within its contract, then restore and drain at a bounded rate. Audit data access and ensure the new service no longer requires write privileges to order tables.')),
s('pitfalls','Trade-offs and tricky cases',table(['Trap','Consequence','Response'],[['One service per entity','Chatty distributed transactions','Model business capability/invariant ownership.'],['Shared DB without ownership','Independent deployments break each other','Restrict writes and migrate through explicit contracts.'],['Event choreography everywhere','Workflow state/ownership becomes invisible','Use an orchestrator or an explicit end-to-end ledger where useful.'],['Premature extraction','Operations overhead exceeds benefit','Enforce module boundaries first.']])+p('Measure lead time, coordinated deployments, dependency failures and operational workload. Service count is not a success metric. A shared team can operate several services, but ownership and on-call capacity must be credible.')),
s('interview','Interview ladder',qa([['Foundational','Monolith versus microservices?','A monolith deploys as a unit; microservices make selected responsibilities independently deployed/operated. Internal modularity is a separate property.'],['Foundational','What is data ownership?','One capability controls authoritative mutation and invariants for its data; others use supported contracts or projections.'],['Intermediate','When should you keep a modular monolith?','When clear modules deliver change isolation and there is no sufficient need for remote deployment/scaling autonomy to justify its cost.'],['Intermediate','Why can shared entity jars cause coupling?','Persistence changes and lockstep versions can spread across services, exposing internals rather than a stable contract.'],['Advanced','How do you extract a side-effecting capability safely?','Establish durable intent/identity, shadow without effects, switch ownership deliberately, preserve compatibility and test rollback/duplicates.'],['Advanced','How do you detect a distributed monolith?','Frequent coordinated releases, shared writes, synchronous chatty chains and inability to tolerate one component’s outage indicate boundaries lack autonomy.']])),
s('references','References and practice',refs([['https://docs.spring.io/spring-modulith/reference/','Spring Modulith','module boundaries and verification.'],['https://www.archunit.org/userguide/html/000_Index.html','ArchUnit','executable code dependency constraints.'],['https://docs.aws.amazon.com/prescriptive-guidance/latest/modernization-decomposing-monoliths/welcome.html','AWS decomposition guidance','migration patterns and boundary choices.']])+p('<strong>Exercise:</strong> choose one candidate extraction and describe the invariant owner, data migration, contract and rollback before drawing new services.'))
]},
{
slug:'rate-limiting',title:'Rate Limiting & Backpressure',heading:'Admit only the work the system can finish usefully',intro:'Protect checkout from noisy clients and slow dependencies by distinguishing request rate, concurrency, queues, quotas and downstream demand.',definition:'Rate limiting bounds admitted operations over time. Backpressure controls production/admission in response to consumption capacity. A concurrency limit bounds simultaneous work; a quota bounds consumption over a longer accounting period.',prerequisites:'Read <a href="scalability.html#measure">throughput and concurrency</a> and <a href="reliability.html#deadlines">deadlines</a>. We begin with a finite worker pool, not a limiter algorithm.',outcome:'Choose a fair admission policy, implement atomic accounting and design controlled behavior during limiter failure.',sections:[
s('problem','A fast caller can consume a slow service',p('One partner sends 1,000 requests/s. Another sends ten. Every request takes one second in the payment provider, so admitting 1,000/s creates roughly 1,000 in-flight operations at steady state. A rate limit alone may still permit far more concurrent work than connections can support.')+p('First decide what is scarce: arrivals per second, simultaneous provider calls, queued memory or monthly partner usage. These are different budgets. Backpressure communicates or enforces reduced demand rather than hiding unlimited work in memory.')),
s('requirements','Define fairness and overload semantics',req(['Apply per-partner and global admission limits.','Protect payment-call concurrency and queue size.','Tell rejected clients how to recover.'],['One tenant must not starve others.','No unbounded queues or retries.','Distributed limit precision is specified.','Limiter outage behavior is explicit per operation.'])+p('A business command rejected before acceptance should cause no side effect. Once accepted durably, responsibility changes: the service must complete or report its terminal failure through the stated protocol. Do not count a queued 202 as successful completion.')),
s('algorithms','Choose an algorithm from burst behavior',table(['Algorithm','Behavior','Trade-off'],[['Fixed window','Count requests in aligned periods','Can admit a double burst around a boundary.'],['Sliding log/window','Account over a moving interval','More storage/work or approximation.'],['Token bucket','Tokens refill; capacity permits a bounded burst','Refill, capacity and cost units need definition.'],['Leaky bucket','Drain at a controlled rate','Queue delay/overflow policy matters.']])+p('A token bucket with capacity 100 and refill 10/s allows a saved burst of 100, then roughly 10/s over time. It does not guarantee a limit of ten requests in every individual second. Assign weighted cost if an export is more expensive than a tiny status read.')+code('Atomic token-bucket decision (conceptual):\n elapsed = max(0, now - lastRefill)\n tokens = min(capacity, tokens + elapsed * refillRate)\n if tokens < cost: reject without mutation/effect\n else: tokens -= cost; admit\nPersist balance + refill timestamp atomically.')+p('Validate clocks and numeric bounds. Concurrent read-modify-write from Java without an atomic store operation can overspend tokens.')),
s('distributed','One limit across many replicas',p('A local bucket per pod multiplies available tokens as pods increase. That may be an acceptable documented approximation, but it is not a strict global budget. A Redis script or suitable conditional store mutation can atomically evaluate one bucket; it adds latency, hot-key pressure and a shared failure dependency.')+p('Layer coarse edge protection, per-tenant limits and resource-specific concurrency control. Exact global fairness may need more coordination than the API can afford. Avoid turning the limiter into a single hot key for every request. Local fallback allocations can improve resilience only if overshoot is understood.')+diagram(['Edge admission','Tenant budget','Dependency concurrency','Bounded work queue'], 'Passing one budget does not bypass the others. Each protects a different resource.')),
s('implementation','REST, Spring and AWS mapping',p('For a documented client rate policy, return 429 with useful retry guidance such as Retry-After. For temporary service-wide unavailability, a documented 503 may be appropriate. Include a stable error code, avoid leaking other tenants’ usage and cap automatic retries within the caller deadline.')+p('Spring filters/interceptors can perform ingress admission; Resilience4j bulkheads can protect dependency concurrency. Bucket4j offers token-bucket mechanisms and integration options; choose the storage/integration matching your required scope. API Gateway usage plans/throttling are useful admission controls but should not be treated as guaranteed hard billing/security quotas without checking their documented semantics.')+p('SQS or a bounded executor can buffer permitted work. Reactive-stream demand can signal consumer capacity within supported pipelines; an unbounded broker backlog is still overload. Check queue age, not just size.')),
s('worked','Worked design: noisy export partner',p('A partner submits many large exports while interactive checkout shares the DB. Give exports separate per-tenant admission and worker-concurrency budgets, with a bounded pending-job quota. Persist accepted jobs and enforce uniqueness/idempotency. Reject excess before scheduling more work.')+p('Workers acquire a bounded DB/query slot and release it on success, failure or interruption. Use a lease/reclaim protocol for distributed permits rather than an in-memory count that never recovers after a crash. Avoid hoarding a permit while waiting for a long retry timer.')+p('Test simultaneous requests across replicas, fixed-window boundary bursts, worker death, Redis latency/outage and tenant skew. Choose fail-closed for a protected costly mutation if accepting uncontrolled work is unsafe; a public noncritical read may use a separate conservative fallback. State that choice before the incident.')),
s('pitfalls','Pitfalls and observability',table(['Trap','Fix'],[['Return 429 after committing a side effect','Make admission precede acceptance or return the accepted identity/outcome.'],['Use IP as user identity behind a proxy','Resolve trusted identity and proxy boundary; shared IPs can penalize unrelated users.'],['Retry every rejection immediately','Honor backoff/deadline and cap attempts.'],['Global limit hides one noisy tenant','Track bounded tenant cohorts or controlled diagnostics plus per-tenant policy.']])+p('Monitor admitted/rejected work, concurrent operations, wait time, oldest job and limiter latency/errors. Confirm the limiter improves completed work and fairness rather than simply moving the queue into the client fleet.')),
s('interview','Interview ladder',qa([['Foundational','Rate versus concurrency limit?','Rate bounds arrivals over time; concurrency bounds simultaneous resource use. Slow calls can exhaust concurrency even under a modest rate.'],['Foundational','What does backpressure mean?','A mechanism that reduces or bounds upstream demand based on downstream capacity, instead of allowing indefinite accumulation.'],['Intermediate','Why can fixed windows burst at boundaries?','A client can spend one full allowance just before reset and another just after, concentrating two windows of traffic into a short interval.'],['Intermediate','Can per-pod buckets enforce a strict global limit?','Not by themselves. Replicas multiply budgets unless the protocol partitions or coordinates a global allowance.'],['Advanced','Fail open or fail closed when Redis fails?','Choose per operation from abuse/cost/correctness and availability requirements; use a bounded tested fallback if allowed, not an improvised universal rule.'],['Advanced','How do you prevent lost permits after worker death?','Use bounded leases/reclamation with correct ownership/expiry and, where protected effects require it, fencing. Test paused workers as well as clean process termination.']])),
s('references','References and practice',refs([['https://docs.aws.amazon.com/apigateway/latest/developerguide/api-gateway-request-throttling.html','API Gateway throttling','limits and behavior.'],['https://www.rfc-editor.org/rfc/rfc6585','HTTP 429','Too Many Requests semantics.'],['https://bucket4j.com/','Bucket4j','token buckets and integrations.'],['https://www.reactive-streams.org/','Reactive Streams','bounded asynchronous demand contracts.']])+p('<strong>Exercise:</strong> name the unit, scope, burst allowance, enforcement precision and outage policy for each limit in one API.'))
]},
{
slug:'replication-partitioning',title:'Replication & Partitioning',heading:'Copy data for resilience, divide data for capacity',intro:'Follow a growing order store through read replicas, failover, sharding keys, hot partitions and safe rebalancing.',definition:'Replication maintains copies of data across nodes. Partitioning divides a dataset or workload into separately managed subsets. These mechanisms can be combined, but they address different capacity and failure questions.',prerequisites:'Read <a href="databases.html">Databases</a> and <a href="consistency.html#models">consistency guarantees</a>. We begin with one writer and one replica.',outcome:'Choose keys and replication policy, identify failover data-loss risks, and describe a rebalancing protocol.',sections:[
s('problem','The order database reaches two different limits',p('Browsing reads consume the database while write volume still fits. A read replica may relieve permitted reads. Months later, write/storage capacity becomes the bottleneck. Another read replica does not necessarily divide the writer’s work. Partitioning may now be relevant.')+p('A third issue appears when the writer fails: which replica may become authoritative, and what committed writes does it contain? Capacity and failure recovery intersect here. Define acknowledgement and promotion rules before assuming copies are interchangeable.')),
s('requirements','List routing and recovery guarantees',req(['Route order lookup and recent-order queries.','Continue or recover after writer loss.','Move data when partitions grow.'],['Define RPO for acknowledged writes.','Read-your-writes for critical user paths.','Prevent stale writers after promotion.','Avoid hotspots and preserve tenant isolation during movement.'])+p('Measure data volume, key-frequency distribution and access locality. A partition containing 10% of rows can receive 90% of requests. Equal row counts do not imply balanced load.')),
s('replicas','Follow a write to its replicas',diagram(['Writer accepts change','Replicate log/state','Replica applies change','Eligible read or promotion'], 'An asynchronous replica can lag; a write acknowledgement may precede its application.')+p('Synchronous replication waits for specified replica acknowledgement before returning under the configured policy. It can reduce certain loss windows at a latency/availability cost. Asynchronous replication improves decoupling but can leave a lagging promotion candidate missing acknowledged writes. Exact durable/apply guarantees depend on the engine and settings.')+p('Failover must establish one authority, update routing and handle in-flight clients. Fencing prevents the old writer from continuing protected writes after recovery. A successful DNS change does not instantly replace every pooled connection.')),
s('keys','Derive a partition key',table(['Key strategy','Strength','Risk'],[['Range/time','Efficient range scans and lifecycle management','Newest range can become hot.'],['Hash of order ID','Distributes independent order operations','Customer history may scatter across partitions.'],['Tenant ID','Keeps tenant-local work together','One large tenant remains a hotspot.'],['Tenant plus bucket','Splits oversized tenant load','Queries/transactions may need fan-out or another index.']])+p('Choose access paths and transaction locality together. A globally unique external order ID may require a coordinating index/owner if uniqueness spans shards. Do not assume each shard’s local unique constraint enforces a global rule.')+p('Consistent hashing reduces key movement when membership changes relative to a simple modulo mapping under common assumptions. Virtual nodes can smooth assignment; replication placement, weighted capacity and hot keys still require design. The hashing algorithm does not move data safely by itself.')),
s('migration','Rebalance with explicit ownership',code('Conceptual shard move:\n  record migration epoch and source owner\n  copy a consistent dataset / record change position\n  catch up writes while source remains authoritative\n  verify checksums/business counts and lag\n  switch ownership with fencing and routing epoch\n  retain rollback evidence; retire source only after policy permits')+p('Dual writes can diverge if either destination fails. Prefer a tested change-capture/replication protocol with an authoritative writer, or define conflict handling and reconciliation explicitly. During cutover, a stale router must not commit to the old owner. A forwarding layer may help, but it needs epoch and retry semantics.')+p('Spring Data does not choose a safe shard key automatically. RDS read replicas and engine partitioning have distinct capabilities. DynamoDB partition-key design distributes access under service behavior; verify key/index limits and adaptive behavior rather than assuming capacity is uniform for any key.')),
s('worked','Worked design: one oversized merchant',p('Orders are initially routed by merchant ID, preserving merchant-local queries. One merchant dominates writes and scans. First separate analytical/export reads from the OLTP path and inspect indexes. If a split is still needed, assign that merchant several deterministic order buckets with a stable routing version.')+p('Single-order lookups use the order-to-bucket mapping. Recent-order listing merges bounded sorted results or uses a maintained read index; it cannot pretend one local query still serves every shard. Keep cross-bucket invariants under a suitable owner or explicit coordination protocol.')+p('Migrate with copy/catch-up/verification and a fenced ownership switch. Test stale clients, retry during movement, replica lag before promotion and rollback after new-owner writes. Report whether rollback means routing reversal, data catch-up or a more complex reconciliation.')),
s('pitfalls','Failure cases to rehearse',table(['Case','Required reasoning'],[['Promote a lagging replica','Quantify possible lost writes and reconcile acknowledged intents.'],['Old primary returns','Prevent split authority with fencing/epoch policy.'],['Hot key after adding shards','A single key is not split by more partitions alone.'],['Global query across shards','Budget fan-out, partial failure and pagination/ordering.']])+p('Track per-shard latency, traffic, storage, replication lag and rebalancing progress. A fleet average can hide one overloaded shard. Backups remain essential because corruption/deletion can replicate correctly.')),
s('interview','Interview ladder',qa([['Foundational','Replication versus partitioning?','Replication copies; partitioning divides. A partition can itself have replicas for availability.'],['Foundational','Does a read replica scale all writes?','No. It can serve suitable reads, while the primary write path may remain the bottleneck.'],['Intermediate','Why is tenant ID sometimes a poor key?','It gives locality but can concentrate a very large tenant on one partition. Evaluate actual size and traffic skew.'],['Intermediate','What does consistent hashing not solve?','It does not guarantee hot-key balance, transaction locality, replica placement or correct migration/fencing.'],['Advanced','How do you prevent stale writes during a shard move?','Use an authoritative ownership/epoch protocol enforced at the write boundary, then copy/catch up/verify and switch with defined retries.'],['Advanced','How do you enforce uniqueness across shards?','Assign a suitable global owner/index or coordination protocol, or redefine the uniqueness scope. Independent local constraints do not enforce a global rule.']])),
s('references','References and practice',refs([['https://www.postgresql.org/docs/current/warm-standby.html','PostgreSQL replication','standby and failover behavior.'],['https://www.postgresql.org/docs/current/ddl-partitioning.html','PostgreSQL partitioning','table partitioning scope and limitations.'],['https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/bp-partition-key-design.html','DynamoDB partition keys','distribution and hot-key considerations.'],['https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_ReadRepl.html','RDS read replicas','replication and promotion semantics.']])+p('<strong>Exercise:</strong> choose a shard key, then describe how one large tenant and one global uniqueness rule challenge it.'))
]},
{
slug:'deployment-runtime',title:'Deployment & Runtime',heading:'Release new code without losing accepted work',intro:'Connect Java process behavior to container lifecycle, Kubernetes routing, rolling delivery and data-compatible rollback.',definition:'Deployment changes the running version/configuration of a service. The runtime lifecycle governs startup, readiness, serving, draining and termination; safe delivery preserves the API and data contract across versions and failures.',prerequisites:'Read <a href="networking.html">Networking</a> and <a href="messaging.html#ack">message acknowledgement</a>. A container packages a process; orchestration schedules and manages it.',outcome:'Design probes, shutdown and rollout limits from actual workload behavior, and explain what rollback can and cannot undo.',sections:[
s('problem','A healthy rollout loses a background task',p('Kubernetes replaces a pod. The process exits with code zero and the deployment becomes green, but a receipt task that existed only in memory disappears. A successful deployment says desired replicas are running; it does not prove accepted business work survived.')+p('Follow one instance through startup, readiness, serving and termination. At each transition, ask whether it can accept new traffic and who owns unfinished work. We can then select probes and grace periods based on behavior rather than copying YAML.')),
s('requirements','Define release safety',req(['Roll out a Spring service and route to ready instances.','Drain in-flight HTTP and reclaim interrupted jobs.','Roll back code when necessary.'],['No lost accepted intent or duplicate protected effect.','Keep enough capacity during rollout/failure.','Use least-privilege runtime identity and bounded resources.','Old/new code must coexist with schema changes.'])+p('A release may change code, database schema, configuration and message contracts. These components do not automatically roll back together. Plan the compatibility interval explicitly.')),
s('lifecycle','Startup, readiness and liveness',table(['Probe/state','Question','Pitfall'],[['Startup','Has initial startup completed?','Aggressive liveness restarts a legitimately slow startup.'],['Readiness','Should this instance receive intended traffic now?','Marking all pods unready for a shared temporary outage can worsen recovery.'],['Liveness','Is restart likely to repair this process?','Restarting healthy processes because a database is down creates churn.']])+p('A pod can be alive but not ready. A process can also be ready for status reads but unable to accept a costly operation; coarse readiness cannot express every route’s admission policy. Use application-level rejection where needed.')+diagram(['Start and initialize','Become ready','Serve within limits','Drain and terminate'], 'Durable jobs can outlive the process. In-memory tasks need an explicit loss policy.')),
s('resources','Requests, limits and graceful shutdown',p('Kubernetes resource requests influence scheduling; limits constrain execution under the runtime’s behavior. CPU throttling can inflate tail latency; memory-limit breaches can kill the process. A JVM heap equal to the container memory limit leaves no room for stacks, native buffers, metaspace or agents.')+code('Illustrative shutdown protocol:\n  stop admitting new application work\n  allow endpoint/routing changes to propagate\n  drain in-flight requests within a bounded grace period\n  commit/abandon work with a durable reclaim protocol\n  close clients and exit before forced termination')+p('Termination hooks, endpoint updates, load-balancer deregistration and application shutdown can overlap. Test their ordering in the actual platform; a fixed sleep alone is not proof of graceful draining. Worker acknowledgement/leases must tolerate hard termination as well as polite shutdown.')),
s('implementation','Spring and deployment strategies',p('Spring Boot supports graceful shutdown and lifecycle timeouts in appropriate server/runtime configurations. Actuator can expose health groups, but management-port health does not necessarily prove the main application port is usable. Restrict management endpoints and test probes against the real serving path.')+table(['Strategy','Benefit','Risk'],[['Rolling','Incrementally replaces replicas','Old/new versions coexist; surge consumes shared DB/provider budget.'],['Blue/green','Switch between complete environments','Extra capacity; routing rollback does not undo new data writes.'],['Canary','Expose a subset and compare outcomes','Small samples can miss rare failures or tenant-specific paths.']])+p('On EKS/ECS, account for node/task startup, AZ placement, connection pools and dependency quotas. A PodDisruptionBudget constrains certain voluntary disruptions; it is not a universal guarantee against node failure, overload or every rollout behavior.')),
s('worked','Worked design: add an order state safely',p('A new release adds PAYMENT_REVIEW. First deploy readers that tolerate the new state without incorrectly shipping orders. Expand schema/constraints and event readers compatibly. Only then enable writers producing the new state. Keep old clients’ behavior documented.')+p('Canary the writer and inspect unknown-state errors, business transitions, latency and queue failures. If rolling back code, confirm the older binary can still read rows/events already produced. If it cannot, disabling the feature or rolling forward may be safer than a blind rollback.')+p('Load-test rollout surge against database connection capacity. Kill a canary during an in-flight payment, verify recovery identity and inspect whether load balancers stopped sending requests within the intended grace. Never make pod readiness the only correctness guard.')),
s('pitfalls','Operational pitfalls',table(['Failure','Mitigation'],[['OOM during warmup','Budget heap plus native memory; observe real startup/steady-state.'],['All pods restart together','Separate dependency health from process liveness.'],['Surge exhausts DB connections','Include deployment replicas in shared-resource budgets.'],['Rollback breaks data readers','Expand/migrate/contract with tested compatibility windows.']])+p('Deploy immutable versioned artifacts and track image digest, config version and schema/event compatibility. Store secrets outside image layers and source. Know the difference between restarting, replacing an instance, rolling back code and restoring data.')),
s('interview','Interview ladder',qa([['Foundational','Readiness versus liveness?','Readiness controls traffic eligibility; liveness indicates whether restarting may recover a process. They should not be identical dependency checks by default.'],['Foundational','Does a container limit equal JVM heap size?','No. Native allocations, stacks, metaspace, buffers and instrumentation also consume memory.'],['Intermediate','Why can a rolling deployment overload a database?','Surge replicas open extra pools and startup/cache-fill work. Count peak rollout resources, not only steady-state replicas.'],['Intermediate','Does a PDB prevent outages?','It governs specified voluntary disruptions under its semantics; it does not prevent all failures or ensure application correctness.'],['Advanced','Why is code rollback not data rollback?','New versions may have committed states/schema/events older code cannot interpret. Plan compatibility before enabling writers.'],['Advanced','How do you verify graceful shutdown?','Exercise real routing/endpoint propagation and hard/soft termination under load, assert bounded draining and durable job recovery, and inspect client-visible outcomes.']])),
s('references','References and practice',refs([['https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/','Pod lifecycle','termination and lifecycle states.'],['https://kubernetes.io/docs/concepts/workloads/controllers/deployment/','Deployments','rollout and availability controls.'],['https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/','Kubernetes probes','distinct probe responsibilities.'],['https://docs.spring.io/spring-boot/reference/web/graceful-shutdown.html','Spring graceful shutdown','server and lifecycle configuration.']])+p('<strong>Exercise:</strong> test termination during a request and a background job, then verify the business ledger rather than only the pod status.'))
]},
{
slug:'disaster-recovery',title:'Disaster Recovery',heading:'Prove you can recover the business state, not just restart servers',intro:'Derive backup, failover, reconciliation and failback choices from acceptable downtime and data loss.',definition:'Disaster recovery restores required service and data after a major failure. Recovery time objective (RTO) is the acceptable recovery duration; recovery point objective (RPO) is the acceptable data-loss window, each defined for a workload and scenario.',prerequisites:'Read <a href="replication-partitioning.html#replicas">replication and failover</a> and <a href="reliability.html">Reliability</a>. A replica and a backup solve different failure cases.',outcome:'Write a measurable recovery protocol with verified data restoration, ownership, reconciliation and return-to-normal steps.',sections:[
s('problem','The replica copied the accidental delete',p('An operator deletes orders with an incorrect predicate. The standby faithfully replicates the delete. Promoting it does not recover the lost records. High availability kept copies current; this incident needs a historical recovery point and a way to reconcile later valid changes.')+p('A regional failure is different again: data may exist elsewhere, but networking, credentials, quotas and dependent providers may not be ready. Start with scenarios and business consequences. “We have backups” is an inventory statement, not a measured recovery capability.')),
s('requirements','Agree on recovery objectives',req(['Restore the order/payment ledger after corruption or regional loss.','Reconcile external provider outcomes and accepted messages.','Return safely to the primary operating model.'],['Example ledger RPO: five minutes; RTO: one hour, validated by drills.','No dual active authority for protected writes.','Recovery artifacts and keys available during the scenario.','Audit evidence and explicit incident ownership.'])+p('Those objectives are illustrative. A payment ledger may need stricter loss handling than a rebuildable search index. Inventory each data class, dependency and contractual obligation rather than imposing one target on the whole estate.')),
s('strategies','Select a recovery posture',table(['Posture','What exists before disaster','Trade-off'],[['Backup/restore','Backups and reproducible infrastructure','Lower steady cost; slower recovery and restore work.'],['Pilot light','Essential data/core components ready','More startup and orchestration at incident time.'],['Warm standby','Reduced running environment','Faster recovery; scaling/quotas still need proof.'],['Active/active','Multiple serving environments','Data ownership, conflicts and split authority become harder.']])+p('Choose from measured recovery duration, cost and correctness, not prestige. Replication lag influences RPO; routing, scaling, validation and operator decisions influence RTO. Active/active does not eliminate recovery from bad writes or compromised credentials.')),
s('backups','Back up enough to reconstruct a valid system',p('Capture data, schema, relevant configuration, event position and required encryption-key access. Point-in-time recovery can restore before an incident when supported, but valid writes after that point may need replay/reconciliation. Test retained event/schema compatibility and provider references.')+p('Keep protection against accidental deletion and inappropriate access with suitable isolation/immutability/retention controls. Do not copy secrets into a general backup artifact without policy. Verify restoration using an isolated environment and meaningful consistency/business checks; a checksum only proves bytes match a reference, not that the reference is business-correct.')+diagram(['Detect and scope incident','Choose recovery point','Restore and validate','Switch authority safely'], 'Failback is a further planned transition, not simply pointing DNS back.')),
s('implementation','AWS and Spring recovery boundaries',p('RDS backup/PITR and snapshot features, S3 versioning/replication and AWS Backup can support different recovery plans. Verify retention, cross-account/region availability, encryption keys and chosen service topology. Infrastructure as code rebuilds configuration; it does not reconstruct missing business data by itself.')+code('Recovery checklist (workload-specific):\n incident scope + write-stop/authority decision\n restore target and time/source position\n schema/config/key availability\n ledger invariants + provider reconciliation\n routes, credentials, quota and capacity validation\n controlled reopen + monitored failback plan')+p('Spring services restarting against a recovered database must tolerate schema/state and replayed messages. Reconcile inbox/outbox positions: a restored ledger may have forgotten an effect a provider already performed. Stable external identity is crucial here; replaying everything as new commands can multiply damage.')),
s('worked','Worked drill: recover checkout after regional failure',p('Declare a regional scenario and start the RTO clock at the agreed point. Establish whether the old writer is fenced/unreachable and choose the secondary data point. Quantify replication loss against the required RPO before reopening writes. Validate order totals, pending payment intents, outbox backlog and provider connectivity.')+p('Restore routing and compute with bounded worker drain. Reconcile payments accepted externally after the secondary’s data point using original provider references/settlement evidence. If history is incomplete, quarantine uncertain work for controlled investigation rather than assuming absence means failure.')+p('When the original region returns, do not allow it to write stale state. Resynchronize or rebuild it from the current authority, validate, then conduct a separately planned failback. Record measured data loss, recovery time, operator actions and deviations for the next drill.')),
s('pitfalls','Recovery mistakes to avoid',table(['Mistake','Consequence'],[['Untested backup','Restore/key/schema dependencies fail under pressure.'],['Failover without fencing','Two writers can commit conflicting protected state.'],['Forget third-party effects','Restored local state can retry already-completed payments.'],['Failback as DNS flip','Old data and pooled connections can reintroduce stale authority.']])+p('Run drills with realistic data size, not an empty database. Measure restore throughput, replay time, DNS/connection behavior and quota approvals. A successful exercise must prove business invariants and the return path, not only that a web page responds.')),
s('interview','Interview ladder',qa([['Foundational','RTO versus RPO?','RTO bounds acceptable recovery duration; RPO bounds acceptable data-loss time window for the specified scenario/workload.'],['Foundational','Why is a replica not a backup?','It may quickly copy deletes/corruption. Historical recovery needs retained points and a tested restore protocol.'],['Intermediate','What must be restored besides rows?','Schema, configuration, access to keys/secrets, event positions, dependencies and enough evidence to reconcile external effects.'],['Intermediate','Does active/active remove DR?','No. Bad writes, compromise and cross-region dependencies can affect every active copy; recovery and ownership still require design.'],['Advanced','How can restoring create duplicate charges?','The restored ledger may lack a completed external effect. Preserve/query provider identity and reconcile before retrying unknown work.'],['Advanced','What proves a DR plan works?','A realistic timed drill demonstrates the declared RPO/RTO, invariants, dependency readiness, controlled authority switch and tested failback.']])),
s('references','References and practice',refs([['https://docs.aws.amazon.com/whitepapers/latest/disaster-recovery-workloads-on-aws/disaster-recovery-options-in-the-cloud.html','AWS DR strategies','postures and trade-offs.'],['https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/USER_PIT.html','RDS point-in-time recovery','restoration mechanics and boundaries.'],['https://docs.aws.amazon.com/aws-backup/latest/devguide/whatisbackup.html','AWS Backup','protection and recovery features.']])+p('<strong>Exercise:</strong> write a one-page runbook for corruption and another for region loss. Identify which steps and recovery points differ.'))
]},
{
slug:'search-pipelines',title:'Search & Data Pipelines',heading:'Build useful projections without losing the source of truth',intro:'Follow committed order changes into search and analytics, then handle duplicates, old events, backfills and rebuilds.',definition:'A data pipeline moves/transforms data between systems. A projection is a derived representation optimized for a read/use case. Change data capture (CDC) observes source changes; stream processing updates results as records arrive, often using event-time and window semantics.',prerequisites:'Read <a href="messaging.html#ordering">event ordering and replay</a> and <a href="databases.html">source-of-truth storage</a>. We introduce search as a derived read path.',outcome:'Design snapshot-plus-change ingestion, choose ordering/late-data rules, and rebuild a projection safely.',sections:[
s('problem','A database filter is not relevance search',p('Customers want to find products by misspelled words, category and relevance. SQL can serve many filters, but a full-text search engine supplies dedicated indexing and ranking mechanisms. Moving product copies into search adds another representation that can lag or diverge.')+p('At the same time, finance wants daily order totals. An analytics model differs from the transactional order model. Rather than make every checkout query a large report, derive a view with a stated freshness contract. Search and analytics share pipeline concerns, but their correctness and query needs differ.')),
s('requirements','Define freshness and authority',req(['Index product/order views for search.','Build daily totals and support correction/backfill.','Rebuild projections while changes continue.'],['Authoritative writes remain in the owning system.','Duplicate/out-of-order data must not corrupt derived state.','Illustrative search freshness under one minute.','Deletes, privacy rules and schema evolution propagate.'])+p('A source row appearing in a search result does not authorize access. Include tenant/visibility filtering and enforce sensitive access at the appropriate authoritative boundary. A search result is not proof of current price or stock.')),
s('index','Understand the search representation',p('An inverted index maps terms to matching documents. Analysis may tokenize, normalize or stem text; exact keyword fields behave differently. Choose mappings for search, exact filters and sort fields deliberately. Accidentally indexing an identifier as analyzed text can produce surprising matches.')+p('An update acknowledgement and search visibility can differ because search engines refresh searchable views on their schedule/configuration. Define acceptable delay instead of forcing an expensive refresh after every write. Track document/source version to diagnose stale results.')+diagram(['Committed source change','CDC / outbox','Transform and validate','Versioned projection'], 'The projection can be rebuilt. Its progress and errors need durable evidence.')),
s('cdc','Snapshot plus changes without a gap',p('Copying all current rows while independently starting a change consumer can miss updates or count them twice. Use a protocol that relates a consistent snapshot to a source log position, then catches up from that position. The connector/database combination determines the actual guarantees.')+code('Illustrative projection event:\n eventId, aggregateId, aggregateVersion, operation, occurredAt, payload\n apply only when the version/order policy permits\n record durable progress after committed projection work\n include tombstones/deletes and schema version handling')+p('CDC can expose low-level row changes, while an outbox can publish intended domain events. Select based on what consumers need and which producer coupling is acceptable. Neither eliminates duplicate delivery. Retention and source-log cleanup must exceed expected outages/catch-up time or require a resnapshot plan.')),
s('time','Event time, windows and corrections',p('Event time records when a fact happened; processing time records when the pipeline handles it. A mobile event can arrive hours late. A window groups events over a time interval; a watermark expresses an engine’s progress/completeness heuristic and late-data policy, not proof that no older event can ever arrive.')+p('For revenue totals, define refunds/corrections and late arrivals. Blindly incrementing a total on every received OrderPaid event double-counts duplicates. Deduplicate by event/source identity, maintain versioned contributions, or use the framework’s appropriate transactional/state guarantees with a clearly defined boundary.')+p('Spark suits many batch/backfill workloads; Flink or Kafka Streams can maintain streaming state where their operational model fits. Select from latency, state size, late-data handling, replay horizon and team expertise—not a generic “real time” label.')),
s('implementation','Spring, AWS and pipeline tools',p('Spring consumers can transform events and update search documents using conditional/version-aware semantics where supported. Debezium offers CDC connectors for supported sources; inspect snapshot, transaction and schema behavior. OpenSearch provides search indexing/querying, while Kafka/MSK, Kinesis and managed processing services offer different transport/runtime contracts.')+p('Batch exports into S3 can feed analytics without burdening the OLTP query path. ETL transforms before the target; ELT loads before transforming in the target’s environment. Neither name guarantees quality. Validate schemas, count records and quarantine malformed data with a recoverable source reference.')+p('Do not place the complete source payload into unrestricted logs when processing fails. Retain replay evidence under access/retention policy and surface actionable error reasons.')),
s('worked','Worked rebuild: change product search mappings',p('Create a new versioned index with the new mapping. Take a source-consistent snapshot plus a compatible change position, populate the new index and catch up live changes. Apply source-version rules so an old snapshot row cannot overwrite a newer change. Verify counts, representative queries, tenant filters, deletes and freshness.')+p('Switch the read alias/routing only when the new view meets the declared criteria. Keep the old index long enough for rollback, but ensure rollback has an explicit freshness strategy. Continue to validate authoritative price/stock during checkout.')+p('Test duplicate events, out-of-order updates, deletion during snapshot, connector outage beyond retention and a corrected refund. A low consumer lag can coexist with a broken projection if bad records are silently discarded. Measure end-to-end source-to-query freshness and reconciliation differences.')),
s('pitfalls','Backfills and failure recovery',table(['Case','Required policy'],[['Backfill replays old side effects','Separate projection rebuilding from email/payment execution.'],['Late event changes a closed report','Define correction, versioning and re-publication semantics.'],['Source log expires','Detect the gap; resnapshot/reconcile rather than claiming continuous progress.'],['Deleted data reappears','Preserve delete/version ordering and purge derived/retained copies per policy.']])+p('Budget backfill I/O, source reads and write load separately from live traffic. Throttle and pause safely. Record source position and transformation version so a result can be reproduced and compared.')),
s('interview','Interview ladder',qa([['Foundational','What is a projection?','A derived representation optimized for a use case, with its own freshness/update behavior and an identified authoritative source.'],['Foundational','Event time versus processing time?','When the fact happened versus when the system handles it. Late delivery can make them far apart.'],['Intermediate','Why is snapshot plus CDC tricky?','A consistent relationship between snapshot contents and the change position is needed to avoid gaps/duplicates and stale overwrite races.'],['Intermediate','Does low consumer lag prove search is correct?','No. Records may be dropped, mis-transformed or invisible due to mappings/refresh. Check end-to-end freshness and reconciliation.'],['Advanced','What does a watermark guarantee?','It supports the engine’s configured event-time progress/late-data policy; it is not a universal assertion that older events cannot arrive.'],['Advanced','How do you rebuild without an outage?','Build a versioned projection, combine snapshot/change capture correctly, validate/catch up, switch routing, and retain a tested rollback/freshness plan.']])),
s('references','References and practice',refs([['https://debezium.io/documentation/reference/stable/','Debezium','source-specific snapshot and change semantics.'],['https://docs.opensearch.org/latest/','OpenSearch','mappings, indexing and search behavior.'],['https://nightlies.apache.org/flink/flink-docs-stable/docs/concepts/time/','Flink event time','timestamps, watermarks and late data.'],['https://kafka.apache.org/documentation/streams/','Kafka Streams','stateful processing and guarantees.']])+p('<strong>Exercise:</strong> design a correction for a duplicated and then refunded order in yesterday’s revenue view.'))
]},
{
slug:'design-practice',title:'End-to-End Design Practice',heading:'Turn requirements into a defensible architecture',intro:'Apply the V4 foundations to six systems. Make each decision traceable to a requirement, invariant, failure or operating constraint.',definition:'System design composes interfaces, data models, processing paths and operating policies to meet explicit requirements. A defensible design explains why each mechanism is needed and what happens when its assumptions fail.',prerequisites:'Use <a href="index.html">API Design</a> plus <a href="databases.html">Databases</a>, <a href="messaging.html">Messaging</a> and <a href="reliability.html">Reliability</a>. Follow the linked specialist lessons when a mechanism is unfamiliar.',outcome:'Conduct a structured interview/design review, then pressure-test six systems with concrete failure and implementation questions.',sections:[
s('problem','Start with the user outcome, not a box collection',p('A familiar product name does not define its requirements. “Design chat” might mean a small team inbox or a global messenger with offline delivery. Ask who uses it, what must work, what may be delayed and what must never happen. Draw the simplest path that meets those answers before adding caches, shards and streams.')+p('Each case below begins with a narrow contract and a primary invariant. The examples are teaching baselines with illustrative targets, not production blueprints for every scale. A design becomes stronger when it states what evidence would force a different choice.')),
s('requirements','Use one review template',req(['Define core operations and access patterns.','Choose authorities, identity and state transitions.','Explain errors, recovery and rollout.'],['Set workload, latency/availability and retention targets.','State invariants and acceptable staleness.','Identify dependency/resource budgets and cost.','Plan security, observability and recovery ownership.'])+code('Interview sequence:\n 1. clarify users, scope and invariants\n 2. estimate workload and data shape\n 3. define APIs/state and authoritative model\n 4. explain read/write paths\n 5. pressure-test concurrency/failure/abuse\n 6. choose scaling and operating policies\n 7. state trade-offs and unresolved assumptions')+p('During an interview, answer the actual follow-up before adding another technology. A small correct design with a clear evolution path is more useful than a large diagram with unexplained guarantees.')),
s('url-shortener','Case 1: URL shortener',p('<strong>Requirements:</strong> create a short alias and redirect it; optionally expire or disable it. Illustrative workload is read-heavy. Invariant: one active alias maps to its intended destination, and private/disabled links follow policy.')+p('<strong>Baseline:</strong> POST /links returns an alias, GET /{alias} resolves it. Use an atomic unique alias insert; random collisions are retried or IDs are allocated under a defined scheme. Store destination, owner, expiry and status. Cache public mappings with an explicit invalidation/freshness policy.')+p('<strong>Decision:</strong> 301/308 permanence can create durable client/intermediary caching, complicating revocation. Use redirect/cache behavior matching the product contract. Never trust arbitrary callback/fetch destinations; if the service previews URLs, that fetch path is SSRF-sensitive. Block abuse and limit creation.')+p('<strong>Spring/AWS:</strong> Spring REST plus DynamoDB conditional writes or SQL unique constraints; CloudFront for appropriately cacheable redirects; WAF/admission controls. Test collisions, stale disabled links, expiry and open-redirect abuse. Scaling reads is easy only if the revocation guarantee permits the cache policy.')),
s('notifications','Case 2: notification service',p('<strong>Requirements:</strong> send email/SMS/push from business events, honor preferences and expose delivery status. Separate accepted, provider-accepted and actually delivered where the provider reports that distinction.')+diagram(['Durable notification intent','Channel queue','Provider attempt','Callback / reconciliation'], 'A provider acceptance timeout creates uncertainty; queue acknowledgement does not prove delivery.')+p('<strong>Baseline:</strong> use an outbox from business producers, stable notification/event identities, a per-channel worker budget and a durable delivery ledger. Resolve templates/preferences under an explicit policy; do not replay historical marketing sends blindly after a rebuild.')+p('<strong>Failure:</strong> provider accepted but response vanished. Reuse provider identity or query delivery evidence; where unsupported, document residual duplicate risk. Rate-limit by tenant/channel and quarantine invalid destinations. Spring consumers plus SQS/SNS/SES or another provider can implement selected pieces; inspect each provider’s actual delivery semantics.')+p('<strong>Test:</strong> duplicate event, provider outage, opt-out change before delayed delivery, secret rotation and bounded backlog drain. Audit delivery without storing unrestricted personal message bodies in logs.')),
s('chat','Case 3: chat with offline delivery',p('<strong>Requirements:</strong> send to a conversation, retrieve history, reconnect and show receipt states. Define whether ordering is per conversation and whether “delivered” means stored, device-received or read.')+p('<strong>Baseline:</strong> assign a stable client message ID and server sequence under a conversation authority. Persist before acknowledging durable acceptance. WebSocket carries live updates, while a history/resume API recovers missed data after disconnect. Presence is an expiring observation, not proof a message was read.')+p('<strong>Data/scaling:</strong> index by conversation and sequence; route conversation writes to an appropriate owner/partition. Large groups introduce fan-out/backpressure and membership-change rules. Authorize history and live subscriptions, not only the initial socket connection.')+p('<strong>Spring/AWS:</strong> WebSocket-capable runtime or API Gateway WebSocket with explicit connection registry/lifecycle, durable storage and workers. Test duplicate sends, reconnect from last sequence, stale membership, out-of-order arrivals and slow clients. A connected socket alone does not guarantee durable delivery.')),
s('booking','Case 4: booking scarce inventory',p('<strong>Requirements:</strong> hold one seat/room interval, confirm payment and expire holds. Invariant: at most one confirmed booking for the protected resource/time scope.')+p('<strong>Baseline:</strong> a conditional mutation/constraint in the authoritative store creates the hold with expiry and stable command identity. Confirmation and expiry compete through conditional transitions. Use the database’s appropriate interval/exclusion or equivalent domain constraint when the rule is about overlapping ranges, not just an exact seat ID.')+p('<strong>Failure:</strong> late payment after hold expiry needs rebooking, void or refund policy. Redis locks can assist contention control but do not replace durable invariant enforcement. Read replicas/search show availability estimates; confirmation uses the authority.')+p('<strong>Spring/AWS:</strong> local Spring/RDS transactions and outbox; SQS schedules recoverable work; an orchestrator can coordinate payment. Test simultaneous last-seat attempts, hold expiry races, duplicate confirmation and a paused worker waking after lease loss. Do not sell “exactly once” from a lock alone.')),
s('files','Case 5: private file storage',p('<strong>Requirements:</strong> upload large files, scan them, authorize downloads, version/delete objects and clean abandoned uploads. Invariant: only authorized clean/eligible content becomes visible.')+p('<strong>Baseline:</strong> create a tenant-scoped upload intent and random object key, issue a short-lived presigned capability, verify stored metadata/checksum, scan in quarantine and conditionally mark READY. For multipart uploads, track finalization and abort or expire abandoned parts.')+p('<strong>Failure:</strong> duplicate object events or scan callbacks must not publish twice or revive deleted versions. Presigned URLs can be reused until effective expiry and are bearer capabilities; do not claim immediate revocation or one-time access without extra controls.')+p('<strong>Spring/AWS:</strong> Spring metadata API, private S3, asynchronous scanning and lifecycle policies. Test checksum mismatch, MIME spoofing, cross-tenant key access, replacement of an object under an existing key and download after permission changes. See API Design’s upload/export sections for a longer implementation walk-through.')),
s('worked','Case 6: payment system walkthrough',p('<strong>Requirements:</strong> create a payment intent, capture once per allowed business intent, query status and refund under policy. Separate authorization, capture, settlement and refund; they are not interchangeable states.')+diagram(['Durable local intent','Stable provider identity','Known / unknown outcome','Reconcile + publish fact'], 'The remote provider is outside the local database transaction.')+p('<strong>Baseline:</strong> scope the caller key, validate fingerprint, persist intent, call the provider with stable identity, and store outcome conditionally. A timeout becomes UNKNOWN when the effect may have happened. Authenticated duplicate/out-of-order webhooks use event identity and state/version guards.')+p('<strong>Failure:</strong> a provider without retry identity or inquiry cannot offer the same single-effect guarantee through arbitrary crashes. State that constraint rather than hiding it behind a distributed lock. Reconciliation uses provider references and settlement records with controlled operator actions.')+p('<strong>Implementation:</strong> Spring/RDS ledger and outbox, SQS reconciliation tasks, provider SDK with explicit retry/timeouts, protected status reads and auditable refund commands. Test every commit/call boundary, repeated refund, restore from an older backup and late success. See <a href="index.html#checkout-design">the detailed API checkout design</a>.')),
s('pitfalls','Cross-case review and trade-offs',table(['Design question','Evidence expected'],[['Where is authority?','One named owner/store for each invariant.'],['What can repeat?','Stable command/event identity and retention horizon.'],['What can be stale?','Operation-specific freshness and cache/replica policy.'],['What happens after a crash?','Commit/ack/call boundaries and recoverable state.'],['How does it scale?','Measured bottleneck and workload distribution.'],['How do we operate it?','SLOs, auditability, runbooks, safe rollout and recovery.']])+p('Finish each design by changing one assumption: a hot tenant, regional failure, strict revocation or a tenfold burst. Explain which part must change and which requirement drives that change. This tests understanding better than memorizing a diagram.')),
s('interview','Interview ladder',qa([['Foundational','What should you clarify first?','Core users/operations, scale, invariants and acceptable delays. The product name alone does not define the design.'],['Foundational','Why not start with a technology list?','It hides the reason for choices. Establish the operation and guarantee, then choose mechanisms that supply them.'],['Intermediate','When should you introduce a cache?','When measured repeated-read cost and a clear freshness/isolation policy justify it, with a protected miss/failure path.'],['Intermediate','How do the six cases share an identity problem?','Retries/replays need stable intent/event identity, while each domain defines which repetitions are legitimate new work.'],['Advanced','How do you answer a region-failure follow-up?','Specify authority, replication/RPO, recovery/RTO, dependency readiness and external-effect reconciliation before claiming multi-region safety.'],['Advanced','What makes a design defensible?','Every component traces to a requirement, its guarantee has a stated scope, and failure/recovery paths are testable with honest limitations.']])),
s('references','References and deliberate practice',refs([['https://www.rfc-editor.org/rfc/rfc9110','HTTP semantics','redirect and method behavior.'],['https://docs.aws.amazon.com/AmazonS3/latest/userguide/using-presigned-url.html','S3 presigned URLs','capability and expiry behavior.'],['https://docs.aws.amazon.com/apigateway/latest/developerguide/apigateway-websocket-api.html','API Gateway WebSocket','connection-oriented service behavior.'],['https://aws.amazon.com/builders-library/making-retries-safe-with-idempotent-APIs/','AWS idempotent APIs','intent and retry recovery.']])+p('<strong>Practice:</strong> take 40 minutes for one case. Spend the first five clarifying, then write a contract, data/invariant model, request paths and two failure timelines. Review against the table above.'))
]}
];
